import pytest
from mcp.shared.auth import InvalidRedirectUriError
from pydantic import AnyUrl

from fastmcp.server.auth.oauth_proxy.models import ProxyDCRClient
from fastmcp.server.auth.redirect_validation import (
    UNSAFE_REDIRECT_URI_SCHEMES,
    matches_allowed_pattern,
    validate_redirect_uri,
)

UNSAFE = [
    "javascript:alert(1)//",
    "JaVaScRiPt:alert(1)",
    "data:text/html,hi",
    "file:///etc/passwd",
    "vbscript:x",
]


def test_scheme_set():
    assert UNSAFE_REDIRECT_URI_SCHEMES == {"javascript", "data", "file", "vbscript"}


@pytest.mark.parametrize("uri", UNSAFE)
@pytest.mark.parametrize("patterns", [None, ["*"], ["javascript:*", "data:*", "file:///*"]])
def test_unsafe_rejected(uri, patterns):
    assert not validate_redirect_uri(uri, patterns)


def test_unsafe_never_matches_pattern():
    assert not matches_allowed_pattern("javascript:alert(1)", "javascript:*")


@pytest.mark.parametrize(
    "uri",
    ["http://localhost:3000", "https://app.example.com", "cursor://a.b/oauth/callback"],
)
def test_ordinary_allowed(uri):
    assert validate_redirect_uri(uri, None)
    assert validate_redirect_uri(None, None)


def test_client_rejects_registered_unsafe():
    client = ProxyDCRClient(
        client_id="c",
        redirect_uris=[AnyUrl("javascript:alert(1)")],
        allowed_redirect_uri_patterns=None,
    )
    with pytest.raises(InvalidRedirectUriError):
        client.validate_redirect_uri(AnyUrl("javascript:alert(1)"))
